/**
 * The app, in German.
 *
 * Keyed on the ENGLISH source string, which is what ui() is handed at the
 * call site. English is the source language and has no table of its own, so
 * a key IS its English text and a miss falls through unchanged.
 *
 * It sits in its own file so it can be FETCHED rather than bundled. Written
 * inline in i18n.ts it had to load with ui(), which every screen imports —
 * so an English app downloaded 235 KB of German chrome at startup and read
 * none of it. i18nFr.ts moved out for the same reason; this followed.
 *
 * Nothing about the entries changed in the move, and nothing should: this is
 * data, and every line of it was written against a string somewhere in the
 * interface.
 */

// UI language follows the learning direction: a German speaker learning
// English (learn-en) gets the app chrome in German. English UI is the source
// key; anything not in the table falls through unchanged, so missing strings
// degrade gracefully instead of breaking.
