  "Type the German you heard": "Tippe den deutschen Satz, den du gehört hast",
  "Type the English you heard": "Tippe den englischen Satz, den du gehört hast",
  "You wrote down what was said.": "Du hast aufgeschrieben, was gesagt wurde.",
  "Play it once more and write what you hear.": "Spiel es noch einmal ab und schreib, was du hörst.",
  "Close enough — watch the spelling": "Nah dran – achte auf die Schreibweise",
  "Hard to catch? Take it as four options instead.": "Schwer zu verstehen? Nimm stattdessen die vier Optionen.",
