  "German picks a different \"you\" for friends, for a group, and for politeness. English uses one word for all three.": "Deutsch wählt ein anderes „du“ für Freunde, für eine Gruppe und für Höflichkeit. Englisch nutzt für alle drei ein Wort.",
  "Nothing matches those filters": "Nichts passt zu diesen Filtern",
  "There is nothing at that level and usefulness together. Widen either one and the queue comes back.": "Auf dieser Stufe und mit dieser Nützlichkeit gibt es zusammen nichts. Erweitere eines von beidem, und die Warteschlange kommt zurück.",
  "Play everything again": "Wieder alles abspielen",
  "Order decides what comes first and still plays everything. This decides what is in the queue at all, so you can work through one level and stop.": "Die Reihenfolge entscheidet, was zuerst kommt, und spielt trotzdem alles. Dies entscheidet, was überhaupt in der Warteschlange ist — so kannst du eine Stufe durcharbeiten und aufhören.",
  "The same bands the word and sentence trackers narrow by, so asking for one here and there means the same thing.": "Dieselben Bänder, nach denen die Wort- und Satzlisten filtern — eines hier zu wählen bedeutet dasselbe wie dort.",
