  "Tips and questions will appear here after the mascot speaks.": "Tipps und Fragen erscheinen hier, nachdem das Maskottchen gesprochen hat.",
  "Yes": "Ja",
  "No": "Nein",
  "Drag": "Ziehe",
  "to move. Right-click for options.": "zum Verschieben. Rechtsklick für Optionen.",
  "to move. Click for messages or right-click for options.": "zum Verschieben. Klicke für Nachrichten oder nutze den Rechtsklick für Optionen.",
  "Ready when you are.": "Bereit, wenn du es bist.",
  "Let's practise some German.": "Lass uns etwas Deutsch üben.",
  "Los geht's! Let's go.": "Los geht's!",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Deutsch-Tipp: Wenn ein Wort der, die oder das verwendet, lerne beides zusammen — also „der Tisch“ statt nur „Tisch“.",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Deutsch-Tipp: In einem normalen deutschen Satz steht das Verb an zweiter Stelle — „Heute gehe ich nach Hause.“",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Deutsch-Tipp: Nach weil oder dass kommt das Verb ans Ende — „weil ich müde bin“.",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Deutsch-Tipp: Deutsche Wörter für Personen, Orte, Dinge oder Ideen beginnen immer mit einem Großbuchstaben.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Deutsch-Tipp: Manche Verben werden im Satz geteilt — aus „aufstehen“ wird „Ich stehe um sieben auf.“",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Englisch-Tipp: In normalen Sätzen kommt zuerst, wer oder was handelt, dann die Handlung und dann der Rest — „I read the book.“",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Englisch-Tipp: Nach can, must, should oder will kommt das Verb ohne „to“ — „can go“, nicht „can to go“.",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Englisch-Tipp: Bei Gewohnheiten oder Fakten endet das Verb mit he, she oder it meistens auf -s — „she works“, „he knows“.",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Englisch-Tipp: Beschreibende Wörter stehen normalerweise vor dem Wort, das sie beschreiben — „a red car“. Sie bleiben gleich — „a nice man“, „a nice woman“.",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Englisch-Tipp: Wähle „a“ oder „an“ nach dem Klang, nicht nach der Schreibweise — „a university“, aber „an hour“.",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Englisch-Tipp: Nach „didn't“ verwendest du go, see oder do — nicht went, saw oder did: „I didn't go.“",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Englisch-Tipp: „cannot“ wird als ein Wort geschrieben. Die Kurzform ist „can't“.",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Englisch-Tipp: Aus „will not“ wird „won't“, niemals „willn't“.",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Englisch-Tipp: Das deutsche „es gibt“ wird bei einer Sache zu „there is“ und bei mehreren zu „there are“ — niemals „it gives“.",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Englisch-Tipp: Wenn du über die Vergangenheit sprichst, verwendest du bei einer Sache „there was“ und bei mehreren „there were“.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Englisch-Tipp: Verwende nicht zwei Verneinungen zusammen — „I didn't see anything“, nicht „I didn't see nothing“.",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Englisch-Tipp: Aus „should not“ wird „shouldn't“. Genauso entstehen „wouldn't“, „couldn't“ und „mustn't“.",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Englisch-Tipp: Verwende „haven't“ mit I, you, we oder they und „hasn't“ mit he, she oder it — „I haven't seen it yet“.",
