  "Click a cell — translate the German word to reveal it safely. Wrong answer = mine.": "Klicke auf ein Feld und übersetze das deutsche Wort, um es sicher aufzudecken. Eine falsche Antwort löst eine Mine aus.",
  "Click a cell and translate the prompt to reveal it safely. Wrong answer = mine.": "Klicke auf ein Feld und übersetze die Vorgabe, um es sicher aufzudecken. Eine falsche Antwort löst eine Mine aus.",
