  "Move the catcher with ← → to collect the glowing letters in order. Catch a wrong letter and it's game over.": "Bewege den Fänger mit ← → und sammle die leuchtenden Buchstaben der Reihe nach. Ein falscher Buchstabe beendet das Spiel.",
  "Tap the glowing letter to spell the German word. Hit a wrong letter and it's game over.": "Tippe den leuchtenden Buchstaben an, um das deutsche Wort zu buchstabieren. Ein falscher Buchstabe beendet das Spiel.",
  "Move with ← → and shoot with Space. Hit the right form of the verb. Wrong answer = game over.": "Bewege dich mit ← → und schieße mit der Leertaste. Triff die richtige Verbform. Eine falsche Antwort beendet das Spiel.",
  "Eat the glowing word-blocks in order to build the German sentence. Wrong word = game over.": "Sammle die leuchtenden Wortblöcke der Reihe nach, um den deutschen Satz zu bilden. Ein falsches Wort beendet das Spiel.",
  "Eat the glowing letters in order to spell the German word. Wrong letter = game over.": "Sammle die leuchtenden Buchstaben der Reihe nach, um das deutsche Wort zu buchstabieren. Ein falscher Buchstabe beendet das Spiel.",
  "Eat the glowing word-blocks in order to build the target sentence. Wrong word = game over.": "Sammle die leuchtenden Wortblöcke der Reihe nach, um den Zielsatz zu bilden. Ein falsches Wort beendet das Spiel.",
  "Eat the glowing letters in order to spell the target word or phrase. Wrong letter = game over.": "Sammle die leuchtenden Buchstaben der Reihe nach, um das Zielwort oder den Zielsatz zu buchstabieren. Ein falscher Buchstabe beendet das Spiel.",
  "Arrow keys or WASD to move · Eat the highlighted letter next": "Bewege dich mit den Pfeiltasten oder WASD · Sammle als Nächstes den markierten Buchstaben",
  "← → arrow keys to move · Catch the glowing letter next": "Bewege dich mit ← → · Fange als Nächstes den leuchtenden Buchstaben",
  "Tap the glowing letter · Don't let it escape": "Tippe den leuchtenden Buchstaben an · Lass ihn nicht entkommen",
  "← → to move · Space to shoot · Hit the right form of the verb": "Mit ← → bewegen · Mit der Leertaste schießen · Triff die richtige Verbform",
  "Complete the sentence": "Vervollständige den Satz",
