  "Click any cell to reveal it. Translate the German word correctly to defuse it. Wrong answer = boom.": "Klicke auf ein Feld. Übersetze das deutsche Wort richtig, um es zu entschärfen. Eine falsche Antwort löst die Mine aus.",
  "Click any cell to reveal it. Translate the prompt correctly to defuse it. Wrong answer = boom.": "Klicke auf ein Feld. Übersetze die Vorgabe richtig, um es zu entschärfen. Eine falsche Antwort löst die Mine aus.",
