  "Click to reveal · Right-click or use Flag mode to mark mines · Translate correctly to defuse": "Klicken zum Aufdecken · Rechtsklick oder Markierungsmodus zum Markieren · Richtig übersetzen zum Entschärfen",
  "Collect the correct articles to grow your snake!": "Sammle die richtigen Artikel, damit deine Schlange wächst!",
  "Collect the English word or phrase that matches the German prompt!": "Sammle das englische Wort oder den englischen Satz, der zur deutschen Vorgabe passt!",
  "Target Article": "Zielartikel",
  "Progression:": "Fortschritt:",
  "Translations this round": "Übersetzungen in dieser Runde",
  "Find its English match in the arena.": "Finde die passende englische Übersetzung in der Arena.",
  "Enter the Arena": "Betritt die Arena",
  "Master the German articles! Guide your snake to consume words that match your target. Watch out for world boundaries and enemy bots!": "Meistere die deutschen Artikel! Führe deine Schlange zu Wörtern mit dem passenden Zielartikel. Achte auf die Spielfeldgrenzen und gegnerische Schlangen!",
  "Read the German prompt, then steer into its English translation. Every correct answer gives you a new phrase. Avoid the wrong choices and enemy snakes.": "Lies die deutsche Vorgabe und steuere dann in die englische Übersetzung. Nach jeder richtigen Antwort erhältst du einen neuen Satz. Weiche falschen Antworten und gegnerischen Schlangen aus.",
  "Start slithering": "Schlange starten",
  "Resume game": "Spiel fortsetzen",
  "Quit to Menu": "Zum Menü",
  "Crashed": "Zusammenstoß",
  "Final Score": "Endpunktzahl",
  "High Score": "Rekord",
  "How to play": "Spielanleitung",
  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Bewege die Maus zum Lenken. Halte die Maustaste oder Leertaste gedrückt, um schneller zu werden; das kostet Punkte. Sammle Wörter mit dem Zielartikel, um zu wachsen. Weiche gegnerischen Schlangen aus. Trifft eine davon deinen Körper, erhältst du Bonuspunkte.",
  "Move your mouse to steer. Hold click or Space to boost. Read the German prompt and collect its English translation. Wrong choices cost points; enemy snakes end the run.": "Bewege die Maus zum Lenken. Halte die Maustaste oder Leertaste für einen Boost gedrückt. Lies die deutsche Vorgabe und sammle ihre englische Übersetzung. Falsche Antworten kosten Punkte; gegnerische Schlangen beenden die Runde.",
  "German clue": "Deutscher Hinweis",
  "English choices": "Englische Auswahl",
  "Correct match": "Richtige Übersetzung",
  "Boost": "Tempo",
  "Consume the city to grow. Use your mouse to steer!": "Verschlinge die Stadt, um zu wachsen. Lenke mit der Maus!",
  "Size": "Größe",
  "You are a black hole in a German city. Eat small objects to grow. Once you're big enough, you can consume cars, trees, and even houses!": "Du bist ein schwarzes Loch in einer deutschen Stadt. Verschlinge kleine Gegenstände, um zu wachsen. Sobald du groß genug bist, kannst du Autos, Bäume und sogar Häuser verschlingen!",
  "Collect city objects while learning their English names. Start small, grow steadily, and avoid larger rivals.": "Sammle Gegenstände aus der Stadt und lerne ihre englischen Namen. Beginne klein, wachse gleichmäßig und weiche größeren Gegnern aus.",
  "Start consuming": "Sammeln starten",
  "Press ESC to pause · Mouse to steer": "ESC zum Pausieren · Mit der Maus lenken",
  "Press ESC to pause · Mouse or WASD to steer": "ESC zum Pausieren · Mit Maus oder WASD lenken",
