  "Keep a conversation going and say how you really feel.": "Halte ein Gespräch am Laufen und sage, wie du dich wirklich fühlst.",
  "React naturally, express moods, and fill pauses like a native.": "Reagiere natürlich, drücke Stimmungen aus und fülle Gesprächspausen.",
  "The one-liners Germans actually shoot back in conversation. Where a phrase is a clip of a fuller sentence, the note shows the full form — so you learn the word order too.": "Kurze Antworten, die im Gespräch wirklich verwendet werden. Bei verkürzten Sätzen zeigt der Hinweis auch die vollständige Form.",
  "React fast and naturally, the way people really talk.": "Reagiere schnell und natürlich, wie Menschen wirklich sprechen.",
  "German conversation basics": "Grundlagen für Gespräche",
