  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched. Continue?": "Der Import ersetzt die gespeicherten Daten dieses Profils. Gemeinsame Einstellungen und eigene Wörter gelten auch für die lokale App auf diesem Computer. Andere Profile bleiben unberührt. Fortfahren?",
  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched.": "Der Import ersetzt die gespeicherten Daten dieses Profils. Gemeinsame Einstellungen und eigene Wörter gelten auch für die lokale App auf diesem Computer. Andere Profile bleiben unberührt.",
