  "Polish": "Polnisch",
  "Read, listen, type and translate real Polish.": "Lies, höre, tippe und übersetze echtes Polnisch.",
  "Polish voice": "Polnische Stimme",
  "Portuguese voice": "Portugiesische Stimme",
