  "Polish translation...": "Polnische Übersetzung ...",
  "Polish tip: there are no articles at all — “dom” is house, a house and the house, all at once.": "Polnisch-Tipp: Es gibt überhaupt keine Artikel — „dom“ heißt Haus, ein Haus und das Haus zugleich.",
  "Polish tip: a negated verb takes the genitive — “lubię kawę”, but “nie lubię kawy”.": "Polnisch-Tipp: Nach einer Verneinung steht der Genitiv — „lubię kawę“, aber „nie lubię kawy“.",
  "Polish tip: the ending already says who — “idę” is I am going, so “ja idę” puts the stress on the I.": "Polnisch-Tipp: Die Endung sagt schon, wer gemeint ist — „idę“ heißt ich gehe, „ja idę“ betont also das Ich.",
  "Polish tip: verbs come in pairs — “robić” is doing it, “zrobić” is getting it done.": "Polnisch-Tipp: Verben kommen paarweise — „robić“ ist das Tun, „zrobić“ das Fertigwerden.",
  "Polish tip: to a stranger it is Pan or Pani, never ty — “Czy mówi Pan po angielsku?”.": "Polnisch-Tipp: Fremde spricht man mit Pan oder Pani an, nie mit ty — „Czy mówi Pan po angielsku?“.",
  "Polish tip: the stress is almost always on the second-to-last syllable — dzię-KU-ję, ksią-ŻKA.": "Polnisch-Tipp: Die Betonung liegt fast immer auf der vorletzten Silbe — dzię-KU-ję, ksią-ŻKA.",
  "Polish tip: “ó” and “u” sound identical, and so do “rz” and “ż” — which is why Polish children are drilled on them too.": "Polnisch-Tipp: „ó“ und „u“ klingen gleich, ebenso „rz“ und „ż“ — deshalb üben auch polnische Kinder genau das.",
  "Polish tip: nouns change their ending for their job in the sentence — “to jest kawa”, but “piję kawę”.": "Polnisch-Tipp: Substantive ändern ihre Endung je nach Rolle im Satz — „to jest kawa“, aber „piję kawę“.",
  "Read, listen, type and translate real Spanish.": "Lies, höre, tippe und übersetze echtes Spanisch.",
  "Read, listen, type and translate real Italian.": "Lies, höre, tippe und übersetze echtes Italienisch.",
  "Spanish voice": "Spanische Stimme",
