  "Only what a conversation needs — greetings, reactions, plans, family, food. No rooms, no furniture.": "Nur was ein Gespräch braucht — Begrüßungen, Reaktionen, Pläne, Familie, Essen. Keine Zimmer, keine Möbel.",
  "Topic round": "Themenrunde",
  "Words for a subject": "Wörter zu einem Thema",
  "A subject like family or food — pick every word and phrase you'd use for it, then see what you missed.": "Ein Thema wie Familie oder Essen — wähl alle Wörter und Sätze, die du dafür brauchst, und sieh dann, was dir gefehlt hat.",
