  "Order": "Reihenfolge",
  "Levels": "Niveaus",
  "Similar sentences together": "Ähnliche Sätze zusammen",
  "The course's pick": "Die Wahl des Kurses",
  "How Continue learning is put together": "Wie Weiterlernen zusammengestellt wird",
  "The course's pick blends how common a sentence is with how hard it is and how far you are. Easiest first takes all of one level before the next. Most common first takes what people say most, whatever the level. Similar sentences together takes the next sentence and then every sentence that starts the same way — all the “Ich möchte …”, then all the “Kannst du …”. Conversation order takes an exchange as the dialogues have it — a question, then the answer that fits it, then what comes next. Shortest first and Longest first go by length. Reviews come back whatever the order.": "Die Wahl des Kurses verbindet, wie häufig ein Satz ist, mit seiner Schwierigkeit und deinem Stand. Leichteste zuerst nimmt ein ganzes Niveau vor dem nächsten. Häufigste zuerst nimmt, was die Leute am meisten sagen, egal auf welchem Niveau. Ähnliche Sätze zusammen nimmt den nächsten Satz und dann jeden Satz, der genauso anfängt — alle „Ich möchte …“, dann alle „Kannst du …“. Gesprächsreihenfolge nimmt einen Wortwechsel so, wie die Dialoge ihn haben — eine Frage, dann die passende Antwort, dann was darauf folgt. Kürzeste zuerst und Längste zuerst gehen nach Länge. Wiederholungen kommen in jeder Reihenfolge zurück.",
  "Order decides what comes first and still teaches everything. This decides what a sitting draws on at all, so you can work through one level and stop. Reviews are never held back.": "Die Reihenfolge entscheidet, was zuerst kommt, und lehrt trotzdem alles. Das hier entscheidet, woraus eine Sitzung überhaupt schöpft — so kannst du ein Niveau durcharbeiten und aufhören. Wiederholungen werden nie zurückgehalten.",
  "Conversation order": "Gesprächsreihenfolge",
  "Changing this rebuilds the sitting from the start.": "Eine Änderung baut die Sitzung von vorn neu auf.",

