  // LearnView draws uiOr(part.theme, "Konversationsmodul") for every lesson in
  // the list, and uiOr does not fall back to the heading it was handed: it
  // returns table[heading] ?? table[fallback] ?? fallback. So a heading with no
  // entry here was never shown in English — it was shown as the word
  // Konversationsmodul, and 357 lessons were all called the same thing. Only the
  // Portuguese table had them.
  // 
  // A heading that is German already still needs an entry, for exactly that
  // reason: without one it does not fall through to itself, it falls through to
  // Konversationsmodul. Those entries are the heading, copied rather than
  // retyped, because one character out is a key that matches nothing.
  // 
  // The German words inside a heading stay German: they are what the lesson
  // teaches. Schultüte, Glatteis, Azubi, schälen.
