  "The nouns for what you feel — grief to glee, named the way Germans name them.": "Die Substantive für das, was man fühlt — von Trauer bis Jubel, so benannt, wie Deutsche es benennen.",
  "Common words the themed packs never taught, bank ranks 1737–2489.": "Häufige Wörter, die die Themenpakete nie gebracht haben, Bankränge 1737 bis 2489.",
  "Reviewed words no pack taught yet, 1–31 of 156.": "Geprüfte Wörter, die noch kein Paket gebracht hat, 1–31 von 156.",
