  "Type the whole Greek sentence — from the Spanish above.": "Tippe den ganzen griechischen Satz — nach dem Spanischen oben.",
  "Type the whole Greek sentence — from the Italian above.": "Tippe den ganzen griechischen Satz — nach dem Italienischen oben.",
  "Type the whole Greek sentence — from the Portuguese above.": "Tippe den ganzen griechischen Satz — nach dem Portugiesischen oben.",
