  "Your turn — say it in Greek": "Du bist dran — sag es auf Griechisch",
  "Greek repeats": "Griechische Wiederholungen",
  "Greek voice is muted and will be skipped.": "Die griechische Stimme ist stumm und wird übersprungen.",
  "Your turn to say the Greek before it is spoken": "Deine Chance, das Griechische selbst zu sagen, bevor es gesprochen wird",
  "Greek first": "Griechisch zuerst",
  "Greek tip: every word of two or more syllables carries one accent mark, and it shows where the stress falls — καλημέρα, ευχαριστώ.": "Griechisch-Tipp: Jedes Wort mit zwei oder mehr Silben trägt genau einen Akzent, und er zeigt, wo die Betonung liegt — καλημέρα, ευχαριστώ.",
  "Greek tip: a question ends in ; — “Τι κάνεις;” is how are you.": "Griechisch-Tipp: Eine Frage endet mit ; — „Τι κάνεις;“ heißt wie geht's dir.",
  "Greek tip: σ becomes ς at the end of a word — ο φίλος, but οι φίλοι.": "Griechisch-Tipp: σ wird am Wortende zu ς — ο φίλος, aber οι φίλοι.",
  "Greek tip: the ending already says who — “πάω” is I go, so “εγώ πάω” puts the stress on the I.": "Griechisch-Tipp: Die Endung sagt schon, wer gemeint ist — „πάω“ heißt ich gehe, „εγώ πάω“ betont also das Ich.",
  "Greek tip: names take the article too — ο Γιάννης, η Μαρία.": "Griechisch-Tipp: Auch Namen bekommen einen Artikel — ο Γιάννης, η Μαρία.",
